import { BOT_PROFILES, skillForRank } from './BotProfiles';
import { createSeededRandom } from './random';
import type { BotProfile, BotRank, BotSkill } from './types';

export interface RankAnchor { rank: BotRank; rating: number }

/** Anchors keep bot difficulty aligned with the Elo numbers produced by RatingSystem. */
export const RANK_RATING_ANCHORS: readonly RankAnchor[] = [
  { rank: 'Rookie', rating: 760 },
  { rank: 'Amateur', rating: 1000 },
  { rank: 'Pro', rating: 1300 },
  { rank: 'Master', rating: 1650 },
  { rank: 'Legend', rating: 2200 },
];

const lerp = (from: number, to: number, ratio: number): number => from + (to - from) * ratio;

function anchorAt(index: number): RankAnchor {
  const anchor = RANK_RATING_ANCHORS[index];
  if (!anchor) throw new RangeError(`no rank anchor at ${index}`);
  return anchor;
}

function nearestProfile(rating: number): BotProfile {
  let best = BOT_PROFILES[0];
  if (!best) throw new RangeError('bot profile table is empty');
  for (const profile of BOT_PROFILES) {
    if (Math.abs(profile.rating - rating) < Math.abs(best.rating - rating)) best = profile;
  }
  return best;
}

/** Interpolates skill between anchors so matchmaking has no difficulty cliffs. */
export function skillForRating(rating: number): BotSkill {
  const first = anchorAt(0);
  const last = anchorAt(RANK_RATING_ANCHORS.length - 1);
  if (rating <= first.rating) return skillForRank(first.rank);
  if (rating >= last.rating) return skillForRank(last.rank);
  for (let index = 0; index < RANK_RATING_ANCHORS.length - 1; index += 1) {
    const low = anchorAt(index);
    const high = anchorAt(index + 1);
    if (rating < low.rating || rating > high.rating) continue;
    const ratio = (rating - low.rating) / (high.rating - low.rating);
    const from = skillForRank(low.rank);
    const to = skillForRank(high.rank);
    return {
      aimError: lerp(from.aimError, to.aimError, ratio),
      powerError: lerp(from.powerError, to.powerError, ratio),
      simulationSamples: Math.round(lerp(from.simulationSamples, to.simulationSamples, ratio)),
      riskTolerance: lerp(from.riskTolerance, to.riskTolerance, ratio),
      shortcutAwareness: lerp(from.shortcutAwareness, to.shortcutAwareness, ratio),
      planningDepth: Math.round(lerp(from.planningDepth, to.planningDepth, ratio)),
    };
  }
  return skillForRank(last.rank);
}

export function botRankForRating(rating: number): BotRank {
  let best = anchorAt(0);
  for (const anchor of RANK_RATING_ANCHORS) {
    if (Math.abs(anchor.rating - rating) < Math.abs(best.rating - rating)) best = anchor;
  }
  return best.rank;
}

/** Builds an opponent tuned to an exact rating instead of snapping to the nearest preset. */
export function botProfileForRating(rating: number, overrides: { id?: string; displayName?: string } = {}): BotProfile {
  const base = nearestProfile(rating);
  return {
    id: overrides.id ?? `${base.id}-r${Math.round(rating)}`,
    displayName: overrides.displayName ?? base.displayName,
    rank: botRankForRating(rating),
    rating,
    personality: base.personality,
    skill: skillForRating(rating),
  };
}

/** Seeded, rating matched field: closer ratings win, with a little controlled noise. */
export function selectBotOpponents(targetRating: number, count: number, seed: number | string = 'match'): BotProfile[] {
  const random = createSeededRandom(seed);
  const wanted = Math.max(0, Math.min(BOT_PROFILES.length, Math.floor(count)));
  return BOT_PROFILES.map((profile) => ({ profile, weight: Math.abs(profile.rating - targetRating) + (random() - 0.5) * 220 }))
    .sort((a, b) => a.weight - b.weight)
    .slice(0, wanted)
    .map((entry) => entry.profile);
}
