import type { PlayerId } from '../contracts/game';
import type { MatchStanding } from './types';

export const DEFAULT_RATING = 1000;

export type RatingTier = 'Rookie' | 'Amateur' | 'Pro' | 'Master' | 'Legend';

export interface RatingEntry {
  playerId: PlayerId;
  rating: number;
  rank: number;
  gamesPlayed?: number;
}

export interface RatingPlacement {
  playerId: PlayerId;
  rank: number;
}

export interface RatingChange {
  playerId: PlayerId;
  rank: number;
  ratingBefore: number;
  ratingAfter: number;
  delta: number;
  expectedScore: number;
  actualScore: number;
  opponents: number;
}

export interface RatingOptions {
  baseK?: number;
  provisionalK?: number;
  provisionalGames?: number;
  minRating?: number;
  maxRating?: number;
  fieldBonus?: number;
  round?: boolean;
}

export const DEFAULT_RATING_OPTIONS: Required<RatingOptions> = {
  baseK: 32,
  provisionalK: 64,
  provisionalGames: 10,
  minRating: 100,
  maxRating: 3500,
  fieldBonus: 0.08,
  round: true,
};

export function expectedScore(rating: number, opponentRating: number): number {
  return 1 / (1 + 10 ** ((opponentRating - rating) / 400));
}

export function placementScore(rank: number, opponentRank: number): number {
  if (rank < opponentRank) return 1;
  if (rank > opponentRank) return 0;
  return 0.5;
}

export function ratingTier(rating: number): RatingTier {
  if (rating < 900) return 'Rookie';
  if (rating < 1200) return 'Amateur';
  if (rating < 1550) return 'Pro';
  if (rating < 1900) return 'Master';
  return 'Legend';
}

/** Multiplayer Elo: each finish position is scored against every opponent in the field. */
export function computeRatingChanges(entries: readonly RatingEntry[], options: RatingOptions = {}): RatingChange[] {
  const config = { ...DEFAULT_RATING_OPTIONS, ...options };
  const seen = new Set<PlayerId>();
  for (const entry of entries) {
    if (seen.has(entry.playerId)) throw new Error(`duplicate rating entry for ${entry.playerId}`);
    seen.add(entry.playerId);
    if (!Number.isFinite(entry.rating)) throw new Error(`invalid rating for ${entry.playerId}`);
    if (!Number.isFinite(entry.rank) || entry.rank < 1) throw new Error(`invalid finish rank for ${entry.playerId}`);
  }
  const opponents = entries.length - 1;
  if (opponents < 1) {
    return entries.map((entry) => ({
      playerId: entry.playerId,
      rank: entry.rank,
      ratingBefore: entry.rating,
      ratingAfter: entry.rating,
      delta: 0,
      expectedScore: 0.5,
      actualScore: 0.5,
      opponents: 0,
    }));
  }
  const fieldScale = 1 + config.fieldBonus * Math.log2(entries.length / 2);
  return entries.map((entry, index) => {
    let expected = 0;
    let actual = 0;
    for (let other = 0; other < entries.length; other += 1) {
      if (other === index) continue;
      const rival = entries[other];
      if (!rival) continue;
      expected += expectedScore(entry.rating, rival.rating);
      actual += placementScore(entry.rank, rival.rank);
    }
    const games = entry.gamesPlayed ?? config.provisionalGames;
    const kFactor = games < config.provisionalGames ? config.provisionalK : config.baseK;
    const raw = (kFactor * fieldScale * (actual - expected)) / opponents;
    const bounded = Math.min(config.maxRating, Math.max(config.minRating, entry.rating + raw));
    const ratingAfter = config.round ? Math.round(bounded) : bounded;
    return {
      playerId: entry.playerId,
      rank: entry.rank,
      ratingBefore: entry.rating,
      ratingAfter,
      delta: ratingAfter - entry.rating,
      expectedScore: expected / opponents,
      actualScore: actual / opponents,
      opponents,
    };
  });
}

/** Stateful wrapper for the match flow: keeps ratings and game counts between matches. */
export class RatingSystem {
  private readonly ratings = new Map<PlayerId, number>();
  private readonly games = new Map<PlayerId, number>();
  private readonly options: RatingOptions;

  constructor(options: RatingOptions = {}) {
    this.options = options;
  }

  getRating(playerId: PlayerId): number {
    return this.ratings.get(playerId) ?? DEFAULT_RATING;
  }

  getGamesPlayed(playerId: PlayerId): number {
    return this.games.get(playerId) ?? 0;
  }

  setRating(playerId: PlayerId, rating: number, gamesPlayed = 0): void {
    this.ratings.set(playerId, rating);
    this.games.set(playerId, gamesPlayed);
  }

  seed(players: Iterable<{ id: PlayerId; rating: number; gamesPlayed?: number }>): void {
    for (const player of players) this.setRating(player.id, player.rating, player.gamesPlayed ?? 0);
  }

  recordMatch(placements: readonly RatingPlacement[]): RatingChange[] {
    const entries: RatingEntry[] = placements.map((placement) => ({
      playerId: placement.playerId,
      rank: placement.rank,
      rating: this.getRating(placement.playerId),
      gamesPlayed: this.getGamesPlayed(placement.playerId),
    }));
    const changes = computeRatingChanges(entries, this.options);
    for (const change of changes) {
      this.ratings.set(change.playerId, change.ratingAfter);
      this.games.set(change.playerId, this.getGamesPlayed(change.playerId) + 1);
    }
    return changes;
  }

  recordStandings(standings: readonly MatchStanding[]): RatingChange[] {
    return this.recordMatch(standings.map((standing) => ({ playerId: standing.playerId, rank: standing.rank })));
  }
}
